<!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>UNIFCO | طلب خدمة</title><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Cairo:wght@400;500;600;700;800;900&display=swap" rel="stylesheet"><link rel="stylesheet" href="https://unpkg.com/leaflet@1.9.4/dist/leaflet.css"><style>:root{font-family:"Cairo",Tahoma,Arial,sans-serif;--navy:#1e315b;--red:#ce122d;--light:#f8f9fb;--muted:#68758a;--line:#dce3ec}*{box-sizing:border-box}body{margin:0;background:var(--light);color:#132137}.wrap{width:min(980px,94%);margin:28px auto}.top{display:flex;justify-content:space-between;align-items:center;margin-bottom:20px}.logo{width:145px;height:82px;object-fit:contain}.card{background:#fff;border:1px solid #e3e8ef;border-radius:18px;padding:30px;box-shadow:0 12px 34px #13213712}h1{color:var(--navy);margin:0 0 8px}.intro{color:var(--muted);margin:0 0 18px;line-height:1.8}.section{padding:22px 0;border-top:1px solid #edf0f5}.section h3{color:var(--navy);margin:0 0 6px}.hint{color:var(--muted);font-size:12px;line-height:1.7;margin:0 0 14px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}.grid.three{grid-template-columns:1.1fr 1fr 1fr}label{display:grid;gap:7px;font-weight:700;font-size:13px}input,select,textarea{width:100%;padding:12px 13px;border:1px solid #ccd5e2;border-radius:9px;font:inherit;background:#fff;color:#132137;outline:0}input:focus,select:focus,textarea:focus{border-color:#7891b5;box-shadow:0 0 0 3px #1e315b10}textarea{min-height:130px;resize:vertical}.btn{border:0;border-radius:9px;padding:13px 20px;background:var(--red);color:#fff;font:inherit;font-weight:800;cursor:pointer}.btn.secondary{background:var(--navy)}.btn.ghost{background:#fff;color:var(--navy);border:1px solid #bfcadb}.back{color:var(--navy);text-decoration:none;font-weight:700}.err{background:#fdecec;color:#9f1f1f;padding:12px;border-radius:9px;margin-bottom:15px}.map-toolbar{display:flex;gap:9px;flex-wrap:wrap;margin-bottom:10px}.map-status{font-size:12px;color:var(--muted);align-self:center}.map{height:340px;border:1px solid var(--line);border-radius:12px;overflow:hidden;z-index:1}.coords{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-top:10px}.upload{border:1px dashed #b9c5d4;border-radius:12px;padding:16px;background:#fbfcfe}.upload input{padding:9px;background:#fff}.preview-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:9px;margin-top:10px}.preview-grid img{width:100%;height:110px;object-fit:cover;border-radius:8px;border:1px solid var(--line)}.required{color:var(--red)}.submit-row{display:flex;justify-content:flex-start;gap:10px;margin-top:8px}@media(max-width:760px){.grid,.grid.three,.coords{grid-template-columns:1fr}.card{padding:22px}.map{height:300px}.preview-grid{grid-template-columns:1fr 1fr}}</style></head><body><div class="wrap"><div class="top"><img class="logo" src="{{ route('brand.logo') }}" alt="UNIFCO"><a class="back" href="{{ route('public.home') }}">العودة للرئيسية</a></div><form class="card" method="POST" enctype="multipart/form-data" action="{{ route('public.request.store') }}">@csrf<input type="hidden" name="request_type" value="{{ $type }}"><h1>{{ $type === 'QUOTATION' ? 'طلب عرض سعر' : 'طلب صيانة طارئة' }}</h1><p class="intro">{{ $type === 'QUOTATION' ? 'أخبرنا بالخدمة أو المشروع المطلوب وسيتابع الفريق إعداد العرض.' : 'أرسل تفاصيل العطل والموقع وصور المعدة والموعد المطلوب ليتم توجيه الطلب لفريق التشغيل.' }}</p>@if($errors->any())<div class="err">{{ $errors->first() }}</div>@endif<div class="section"><div class="grid"><label>نوع الخدمة <span class="required">*</span><select name="service_category" required><option value="">اختر الخدمة</option>@foreach(['إدارة مرافق متكاملة','مولدات كهربائية','لوحات ATS','محولات كهربائية','UPS والطاقة غير المنقطعة','أنظمة الجهد المتوسط','صيانة وقائية','صيانة تصحيحية','اختبارات وتشغيل','أخرى'] as $service)<option value="{{ $service }}" @selected(old('service_category')===$service)>{{ $service }}</option>@endforeach</select></label><label>المدينة / الموقع المختصر @if($type === 'EMERGENCY_MAINTENANCE')<span class="required">*</span>@endif<input name="site_city" value="{{ old('site_city') }}" @required($type === 'EMERGENCY_MAINTENANCE') placeholder="مثال: الرياض - المنطقة الصناعية"></label></div><label style="margin-top:14px">عنوان الطلب <span class="required">*</span><input name="subject" value="{{ old('subject') }}" required placeholder="مثال: عطل مولد الطوارئ"></label><label style="margin-top:14px">تفاصيل العطل / الطلب <span class="required">*</span><textarea name="details" required placeholder="اشرح الأعراض، وقت بداية العطل، وأي ملاحظات فنية مهمة">{{ old('details') }}</textarea></label></div>@if($type === 'EMERGENCY_MAINTENANCE')<div class="section"><h3>موقع العطل على الخريطة</h3><p class="hint">انقر على الخريطة لتحديد موقع المعدة أو استخدم موقعك الحالي. سيتم حفظ الإحداثيات والعنوان مع الطلب.</p><div class="map-toolbar"><button class="btn secondary" id="use-location" type="button">استخدام موقعي الحالي</button><span class="map-status" id="map-status">لم يتم تحديد موقع بعد</span></div><div id="request-map" class="map"></div><div class="coords"><label>العنوان التفصيلي <span class="required">*</span><input id="site-address" name="site_address" value="{{ old('site_address') }}" required placeholder="اسم الموقع، الشارع، المبنى أو أقرب معلم"></label><label>الإحداثيات<input id="coords-display" value="{{ old('latitude') && old('longitude') ? old('latitude').', '.old('longitude') : '' }}" readonly placeholder="تُملأ تلقائيًا من الخريطة"></label></div><input type="hidden" id="latitude" name="latitude" value="{{ old('latitude') }}"><input type="hidden" id="longitude" name="longitude" value="{{ old('longitude') }}"></div><div class="section"><h3>الموعد المطلوب</h3><p class="hint">اختر التاريخ أولًا ثم الوقت المطلوب للوصول أو بدء أعمال الصيانة.</p><div class="grid"><label>التاريخ المطلوب <span class="required">*</span><input type="date" name="requested_date" value="{{ old('requested_date') }}" min="{{ now()->toDateString() }}" required></label><label>الوقت المطلوب <span class="required">*</span><input type="time" name="requested_time" value="{{ old('requested_time') }}" required></label></div></div><div class="section"><h3>صور الطلب</h3><div class="grid"><div class="upload"><label>صورة المعدة <span class="required">*</span><input id="equipment-image" type="file" name="equipment_image" accept="image/jpeg,image/png,image/webp" capture="environment" required></label><p class="hint">صورة واضحة للمعدة أو اللوحة المتأثرة. JPG / PNG / WebP حتى 8MB.</p><div id="equipment-preview" class="preview-grid"></div></div><div class="upload"><label>صور داعمة للطلب<input id="supporting-images" type="file" name="supporting_images[]" accept="image/jpeg,image/png,image/webp" multiple></label><p class="hint">حتى 6 صور إضافية للعطل أو القراءات أو موقع العمل.</p><div id="supporting-preview" class="preview-grid"></div></div></div></div>@endif<div class="section"><h3>بيانات التواصل</h3><p class="hint">لا يلزم إنشاء حساب. ستستخدم هذه البيانات للتواصل ومتابعة الطلب.</p><div class="grid"><label>اسم الشركة <span class="required">*</span><input name="company_name" value="{{ old('company_name') }}" required></label>@if($type === 'EMERGENCY_MAINTENANCE')<label>المسؤول عن الطلب <span class="required">*</span><input name="responsible_person" value="{{ old('responsible_person') }}" required placeholder="اسم الشخص المسؤول بالموقع"></label>@endif<label>السجل التجاري <span class="required">*</span><input name="commercial_registration" value="{{ old('commercial_registration') }}" required></label><label>البريد الإلكتروني <span class="required">*</span><input type="email" name="email" value="{{ old('email') }}" required></label><label>رقم الجوال <span class="required">*</span><input name="mobile" value="{{ old('mobile') }}" required></label></div></div><div class="submit-row"><button class="btn" type="submit">إرسال الطلب</button></div></form></div>@if($type === 'EMERGENCY_MAINTENANCE')<script src="https://unpkg.com/leaflet@1.9.4/dist/leaflet.js"></script><script>(function(){const latInput=document.getElementById('latitude'),lngInput=document.getElementById('longitude'),addressInput=document.getElementById('site-address'),display=document.getElementById('coords-display'),status=document.getElementById('map-status');const initialLat=parseFloat(latInput.value)||24.7136,initialLng=parseFloat(lngInput.value)||46.6753;const map=L.map('request-map').setView([initialLat,initialLng],latInput.value?16:6);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'© OpenStreetMap'}).addTo(map);let marker=null;function setLocation(lat,lng,reverse=true){lat=Number(lat).toFixed(7);lng=Number(lng).toFixed(7);latInput.value=lat;lngInput.value=lng;display.value=lat+', '+lng;if(marker)marker.setLatLng([lat,lng]);else marker=L.marker([lat,lng],{draggable:true}).addTo(map).on('dragend',function(e){const p=e.target.getLatLng();setLocation(p.lat,p.lng,true)});status.textContent='تم تحديد الموقع';if(reverse){fetch('https://nominatim.openstreetmap.org/reverse?format=jsonv2&accept-language=ar&lat='+lat+'&lon='+lng).then(r=>r.ok?r.json():null).then(data=>{if(data&&data.display_name&&!addressInput.value)addressInput.value=data.display_name}).catch(()=>{});}}map.on('click',e=>setLocation(e.latlng.lat,e.latlng.lng,true));if(latInput.value&&lngInput.value)setLocation(initialLat,initialLng,false);document.getElementById('use-location').addEventListener('click',function(){if(!navigator.geolocation){status.textContent='المتصفح لا يدعم تحديد الموقع';return}status.textContent='جارٍ تحديد موقعك...';navigator.geolocation.getCurrentPosition(pos=>{const {latitude,longitude}=pos.coords;map.setView([latitude,longitude],17);setLocation(latitude,longitude,true)},()=>status.textContent='تعذر الوصول إلى موقعك. حدد الموقع يدويًا على الخريطة.',{enableHighAccuracy:true,timeout:10000})});function previews(inputId,targetId,max){document.getElementById(inputId).addEventListener('change',function(){const target=document.getElementById(targetId);target.innerHTML='';Array.from(this.files).slice(0,max).forEach(file=>{const img=document.createElement('img');img.alt='معاينة';img.src=URL.createObjectURL(file);target.appendChild(img)})})}previews('equipment-image','equipment-preview',1);previews('supporting-images','supporting-preview',6)})();</script>@endif</body></html>